def transform(grid):
    """Connect matching-color horizontal marks across the blank band above 2."""
    g = [row[:] for row in grid]
    rows, cols = len(g), len(g[0])
    # Find the solid horizontal divider colored 2.
    divider = next((r for r, row in enumerate(g) if all(v == 2 for v in row)), None)
    if divider is None:
        return g
    # Same-color marks on the two sides specify the connector columns.
    top = next((r for r in range(divider) if any(g[r][c] != 0 and g[r][c] != 2 for c in range(cols))), None)
    bottom = next((r for r in range(divider + 1, rows) if any(g[r][c] != 0 and g[r][c] != 2 for c in range(cols))), None)
    if top is None or bottom is None:
        return g
    topcols = {c for c, v in enumerate(g[top]) if v != 0 and v != 2}
    botcols = {c for c, v in enumerate(g[bottom]) if v != 0 and v != 2}
    color = next((g[top][c] for c in topcols if g[top][c] in [g[bottom][x] for x in botcols]), None)
    if color is None:
        return g
    cols_to_fill = {c for c in topcols if g[top][c] == color} & {c for c in botcols if g[bottom][c] == color}
    for c in cols_to_fill:
        for r in range(top + 1, divider):
            if g[r][c] == 0:
                g[r][c] = 4
    return g
